        // Pre-allocate to avoid re-allocations
        result.reserve(arr.len());

        let mut i: usize = 0;
        // Iterate over all indices of `arr`, maintaining the following invariants:
        //   1) 0 <= i <= arr.len()
        //   2) result.len() == i
        //   3) For all j < i, result[j] satisfies the specification
